          "Watch complete examples rather than the strongest three seconds of a reel. Can a viewer follow the action? Is the audio usable? Do captions obscure the feature? Does the explanation leave enough time at the difficult step? Discuss the same assignment with candidates, rather than ranking unrelated public view counts or asking several people to deliver a complete usable advertisement for free.\n\nA small paid test can resolve a specific production uncertainty. Define the segment, fee, permitted uses and whether advertising is included. Testing how to show a reflective connector is a bounded task; requesting an entire marketing concept under a test label is not. If a work sample and production discussion already answer the question, another filming exercise may add little.\n\nSeparate necessary conditions from preferences. Fast editing may be unsuitable for an assembly sequence that needs patient explanation. Accent, setting and clothing decisions should relate to the intended audience and assignment, rather than unrelated personal assumptions. Ask how the creator would explain the difficult step and what resources they would need. That provides better evidence than a demand to copy every movement in someone else’s video. Retain a few assignment-specific selection reasons for the later review."
