          "File delivery, ownership and permission to use the content are separate questions. The U.S. Copyright Office overview explains original expression and authorization by rights holders; the actual agreement still needs to fit the relevant jurisdiction and project. Payment, source-file delivery and the label UGC do not automatically mean perpetual worldwide use, unrestricted editing or permission to transfer the work to others.\n\nConfirm the user, channels, territories, term, editing, translations, advertising and renewals separately. Can the brand turn a demonstration into a different testimonial? Are source footage and music included? May a retail partner use the result? Advertising through the creator’s account also has platform conditions; downloading a file does not establish permission to advertise through that account.\n\nKeep a permission record the media buyer and editor can use: asset identifier, allowed use, start and end dates, approving contact, restrictions and evidence location. Resolve both permissions and technical requirements before scheduling production. Otherwise, a well-made asset may arrive without the rights the campaign needs. Treat an expanded request as a new discussion instead of asking an editor to interpret a general instruction that the client needs it."
